def build_program(d4,palette):
    source="from collections import Counter\nBG=__BG__\nHYPOTHESES=tuple((axis,low_a,low_b,boundary) for axis in (0,1) for low_a in (0,1) for low_b in (0,1) for boundary in (False,True))\n\ndef _scene(g):\n    H,W=len(g),len(g[0]);fg={(r,c) for r in range(H) for c in range(W) if g[r][c]!=BG}\n    scenes=[]\n    for hr in [r for r in range(H) if sum(g[r][c]!=BG for c in range(W))>=4]:\n        for vc in [c for c in range(W) if sum(g[r][c]!=BG for r in range(H))>=4]:\n            if any(r!=hr and c!=vc for r,c in fg):continue\n            lines=([g[r][vc] for r in range(H)],g[hr]);skips=(hr,vc);details=[]\n            for line,skip in zip(lines,skips):\n                counts=Counter(v for i,v in enumerate(line) if i!=skip and v!=BG)\n                if len(counts)!=2:break\n                marker=[c for c,n in counts.items() if n==2]\n                thread=[c for c,n in counts.items() if n>2]\n                if len(marker)!=1 or len(thread)!=1:break\n                marks=[i for i,v in enumerate(line) if i!=skip and v==marker[0]]\n                if marks[1]-marks[0]<2:break\n                details.append((thread[0],marker[0],marks))\n            if len(details)!=2:continue\n            if len({v for x in details for v in x[:2]})!=4:continue\n            if g[hr][vc] not in [d[0] for d in details]:continue\n            scenes.append((hr,vc,details))\n    return scenes\n\ndef _outputs(g,hyp):\n    axis,low_a,low_b,boundary=hyp;answers=[]\n    for hr,vc,details in _scene(g):\n        # axis0: across coordinate is row; axis1: across coordinate is column.\n        ct,cmc,cm=details[axis];wt,wmc,wm=details[1-axis]\n        wpos=(hr,vc)[axis]\n        if not (max(cm)<wpos or min(cm)>wpos):continue\n        a0,a1=min(cm+[wpos]),max(cm+[wpos]);b0,b1=min(wm),max(wm)\n        out=[[BG]*len(g[0]) for _ in g]\n        for a in range(a0,a1+1):\n            k=(a-a0) if low_a else (a1-a)\n            for b in range(b0,b1+1):\n                j=(b-b0) if low_b else (b1-b)\n                if k%2==0:col=(cmc if min(cm)<=a<=max(cm) else wmc) if j%2==0 else ct\n                else:col=wt if j%2==0 else g[hr][vc]\n                r,c=(a,b) if axis==0 else (b,a)\n                out[r][c]=col\n        if not boundary:\n            answers.append(out)\n        else:\n            nearest=min(abs(a-wpos) for a in cm)\n            for near in [a for a in cm if abs(a-wpos)==nearest]:\n                painted=[row[:] for row in out]\n                if nearest%2==0:\n                    for b in range(b0,b1+1):\n                        j=(b-b0) if low_b else (b1-b)\n                        if j%2:\n                            r,c=(near,b) if axis==0 else (b,near)\n                            painted[r][c]=g[hr][vc]\n                answers.append(painted)\n    return answers\n\ndef solve(demonstrations,grid):\n    hypotheses=list(HYPOTHESES)\n    for d in demonstrations or []:\n        a,b=(d['input'],d['output']) if isinstance(d,dict) else d\n        hypotheses=[h for h in hypotheses if b in _outputs(a,h)]\n        if not hypotheses:return None\n    outs=[o for h in hypotheses for o in _outputs(grid,h)]\n    if not outs or any(o!=outs[0] for o in outs):return None\n    return outs[0]\n"
    return source.replace('__BG__',str(palette[0]))
